// P4 facade: portico (columns, entablature, ceiling, landing, lanterns), the entry and back doors with fanlight and
// sidelights, the palladian windows, every arch window in OPENINGS with its sill and hood, the three carriage doors,
// and the garage lamp posts. Builds only into air: the shells leave every opening empty, and the portico footprint is
// RESERVED for this part.
import { B, OPENINGS, archOpening, carriageDoor, entryDoor, lampPost, openingsOf, portico } from "../vocab.mjs";

export function build(g) {
  portico(g);
  // Portico lanterns at the two inner bays too (plan Part 4); the vocab already hangs them at x26..27.
  g.set(24, 8, 8, ...B.lantern(true));
  g.set(29, 8, 8, ...B.lantern(true));

  // Entry (z=11) and back door (z=25): doors, sidelights, transom, fan, springers.
  for (const o of openingsOf("entry")) entryDoor(g, o);

  // Glazing with springers, sills and hoods. Interior arches (kind arch) and cased openings stay open.
  for (const o of OPENINGS) if (o.kind === "window" || o.kind === "palladian") archOpening(g, o);

  // Three carriage bays on the street front (z=7).
  for (const x0 of [3, 8, 13]) carriageDoor(g, x0);

  // Lamp posts on the garage piers, between the bays.
  lampPost(g, 7, 6);
  lampPost(g, 12, 6);
}
#!/bin/sh
# Makes build.nbt from scratch: build.mjs to a temp file, then the roof preset check once the shell exists, then mv.
set -eu
cd "$(dirname "$0")"
MCD=/Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs
tmp=build.tmp.nbt
trap 'rm -f "$tmp"' EXIT

node build.mjs "$tmp"

# The roofs are built in node by roofSpec (parts/roofs.mjs), so this preset step is a dry-run report only (it writes
# nothing); running it for real would put a second roof over the first.
if grep -q '^// STUB' parts/main-shell.mjs; then
  echo "roof step skipped: the shell is still a stub"
else
  node "$MCD" roof "$tmp" --preset cottage --style hip --material dark-slate --dry-run
fi

mv "$tmp" build.nbt
echo "wrote build.nbt"
